namespace midnightShow {
class CueListPanel final:public ShapeShifterContentComponent,private ListBoxModel,private Timer {
public:
 ListBox rows;ComboBox type;OwnedArray<TextButton> buttons;Label message;std::vector<std::pair<std::shared_ptr<Cue>,int>> visible;uint64_t seen=0;
 explicit CueListPanel(const String& name):ShapeShifterContentComponent(name){rows.setModel(this);rows.setRowHeight(44);rows.setColour(ListBox::backgroundColourId,Colour(0xff101822));addAndMakeVisible(rows);addAndMakeVisible(type);addAndMakeVisible(message);for(int i=0;i<=6;++i)type.addItem(cueTypeName(CueType(i)),i+1);type.setSelectedId(1);
 add("Add cue",[this]{auto* c=coordinator();Id parent;auto chosen=c->find(c->selected);if(chosen&&(chosen->type==CueType::Group||chosen->type==CueType::Reaction))parent=chosen->id;auto t=CueType(type.getSelectedId()-1);if(chosen&&chosen->type==CueType::Reaction)t=CueType::Step;c->add(t,parent);});
 add("Add step",[]{auto* c=coordinator();auto selected=c->find(c->selected);Id parent;if(selected&&selected->type==CueType::Reaction)parent=selected->id;else if(selected&&selected->type==CueType::Step){std::function<void(const std::vector<std::shared_ptr<Cue>>&)> visit=[&](const auto& items){for(auto item:items){if(item->type==CueType::Reaction)for(auto step:item->children)if(step==selected)parent=item->id;visit(item->children);}};visit(c->cues);}if(parent.empty()){auto routine=c->add(CueType::Reaction);parent=routine->id;}c->add(CueType::Step,parent);});
 add("GO",[]{coordinator()->go();});add("Direct Start",[]{auto* c=coordinator();c->direct(c->selected);});add("GoTo",[]{auto* c=coordinator();c->goTo(c->selected);});
 add("Duplicate",[]{auto* c=coordinator();c->duplicate(c->selected);});add("Up",[]{auto* c=coordinator();c->reorder(c->selected,-1);});add("Down",[]{auto* c=coordinator();c->reorder(c->selected,1);});add("Delete definition",[]{auto* c=coordinator();c->erase(c->selected);});add("Undo",[]{coordinator()->undo();});
 add("Top list",[]{coordinator()->listFocus.clear();});add("Preview (normal outputs)",[]{auto* c=coordinator();c->direct(c->selected,true,true);});
 message.setColour(Label::textColourId,Colours::orange);setWantsKeyboardFocus(true);refresh();startTimerHz(10);
 }
 static ShapeShifterContent* create(const String& s){return new CueListPanel(s);}~CueListPanel()override{stopTimer();rows.setModel(nullptr);}
 void add(const String& text,std::function<void()> action){auto* b=buttons.add(new TextButton(text));addAndMakeVisible(b);b->onClick=[this,action]{try{action();message.setText({},dontSendNotification);refresh();}catch(const std::exception& e){message.setText(e.what(),dontSendNotification);}};}
 void refresh(){auto* c=coordinator();if(!c)return;visible.clear();std::function<void(const std::vector<std::shared_ptr<Cue>>&,int)> visit=[&](const auto& children,int depth){for(auto cue:children){visible.push_back({cue,depth});visit(cue->children,depth+1);}};visit(c->cues,0);rows.updateContent();rows.repaint();for(size_t i=0;i<visible.size();++i)if(visible[i].first->id==c->selected)rows.selectRow(int(i),true,false);seen=c->revision;}
 void timerCallback()override{refresh();}
 int getNumRows()override{return int(visible.size());}
 void selectedRowsChanged(int row)override{if(row>=0&&row<int(visible.size()))coordinator()->select(visible[row].first->id);}
 void paintListBoxItem(int row,Graphics& g,int w,int h,bool selected)override{if(row<0||row>=int(visible.size()))return;auto cue=visible[row].first;auto* c=coordinator();g.fillAll(selected?Colour(0xff264863):Colour(0xff151f2b));bool standby=false;for(auto p:c->standby)standby|=p.second==cue->id;bool active=false;for(auto p:c->runs)active|=p.second->cue->id==cue->id&&(p.second->outcome==Outcome::Pending||c->owns(*p.second));g.setColour(standby?Colours::orange:active?Colours::lightgreen:Colours::whitesmoke);String prefix=standby?"STANDBY  ":active?"ACTIVE  ":"";g.drawFittedText(prefix+cue->title->stringValue()+"\n"+String(cueTypeName(cue->type)),8+visible[row].second*18,1,w-16-visible[row].second*18,h-2,Justification::centredLeft,2);}
 bool keyPressed(const KeyPress& key)override{auto* focus=Component::getCurrentlyFocusedComponent();if(focus!=this&&focus!=&rows)return false;try{if(key.getKeyCode()==KeyPress::spaceKey){coordinator()->go();return true;}}catch(const std::exception& e){message.setText(e.what(),dontSendNotification);}return false;}
 void resized()override{auto r=getLocalBounds().reduced(8);type.setBounds(r.removeFromTop(28));r.removeFromTop(5);for(int line=0;line<4;++line){auto row=r.removeFromTop(29);for(int n=0;n<3;++n)buttons[line*3+n]->setBounds(row.removeFromLeft(row.getWidth()/(3-n)).reduced(2));}message.setBounds(r.removeFromBottom(32));rows.setBounds(r);}
 void paint(Graphics& g)override{g.fillAll(Colour(0xff101822));}
};
class InspectorPanel final:public ShapeShifterContentComponent,private Timer {
public:
 ComboBox part,endTarget;std::vector<Id> endTargets;TextButton addMove{"Add movement"},addLink{"Add Link"},addHaptic{"Add Haptic"},fromTake{"Use recording"};Label title,error;Viewport viewport;std::unique_ptr<InspectableEditor> editor;std::shared_ptr<Cue> selected;Id bound;int actionCount=-1;std::unique_ptr<PackageInspector> packageEditor;std::unique_ptr<FileChooser> packageChooser;
 explicit InspectorPanel(const String& name):ShapeShifterContentComponent(name){for(Component* c:std::initializer_list<Component*>{&part,&endTarget,&addMove,&addLink,&addHaptic,&fromTake,&title,&error,&viewport})addAndMakeVisible(c);part.onChange=[this]{bindEditor();};endTarget.onChange=[this]{int n=endTarget.getSelectedId()-1;if(selected&&n>=0&&n<int(endTargets.size()))selected->target->setValue(String(endTargets[n]));};
 addMove.onClick=[this]{add(Kind::Move);};addLink.onClick=[this]{add(Kind::Link);};addHaptic.onClick=[this]{add(Kind::Haptic);};
 fromTake.onClick=[this]{if(!selected)return;if(selected->type==CueType::Package){packageChooser=std::make_unique<FileChooser>("Choose Custom Behaviour package folder");Component::SafePointer<InspectorPanel> safe(this);packageChooser->launchAsync(FileBrowserComponent::openMode|FileBrowserComponent::canSelectDirectories,[safe](const FileChooser& chooser){if(!safe||!safe->selected)return;auto folder=chooser.getResult();if(!folder.isDirectory())return;try{safe->selected->package=importPackage(folder);safe->selected->parameters=packageParameters(safe->selected->package,var());safe->rebuild();safe->part.setSelectedId(101);safe->error.setText({},dontSendNotification);Engine::mainEngine->changed();}catch(const std::exception& e){safe->error.setText(e.what(),dontSendNotification);}});return;}if(selected->type==CueType::Mapping){PopupMenu menu;auto mappings=nativeMappings();for(size_t i=0;i<mappings.size();++i)menu.addItem(int(i+1),mappings[i]->niceName);Component::SafePointer<InspectorPanel> safe(this);std::vector<String> ids;for(auto m:mappings)ids.push_back(m->showDefinitionId);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&fromTake),[safe,ids](int n){if(safe&&safe->selected&&n>0&&n<=int(ids.size())){safe->selected->sourceMapping->setValue(ids[n-1]);safe->rebuild();}});return;}PopupMenu menu;int n=0;std::vector<Id> ids;for(auto t:recordings()->items)if(t->editable){ids.push_back(t->id);menu.addItem(++n,t->name);}Component::SafePointer<InspectorPanel> safe(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&fromTake),[safe,ids](int result){if(!safe||result<=0||result>int(ids.size())||!safe->selected)return;auto take=recordings()->find(ids[result-1]);if(!take)return;auto b=safe->selected->addMotion();b->loadJSONData(take->movement.getJSONData());safe->selected->recording=take->id;safe->rebuild();safe->part.setSelectedId(int(safe->selected->actions.size()+1));Engine::mainEngine->changed();});};
 error.setColour(Label::textColourId,Colours::orange);startTimerHz(10);}
 static ShapeShifterContent* create(const String& s){return new InspectorPanel(s);}~InspectorPanel()override{stopTimer();viewport.setViewedComponent(nullptr,false);editor.reset();}
 void add(Kind kind){if(!selected)return;selected->addMotion(kind);rebuild();part.setSelectedId(int(selected->actions.size()+1));Engine::mainEngine->changed();}
 void rebuild(){endTarget.setVisible(selected->type==CueType::End);endTarget.clear(dontSendNotification);endTargets.clear();if(selected->type==CueType::End){std::function<void(const std::vector<std::shared_ptr<Cue>>&)> visit=[&](const auto& items){for(auto cue:items){if(cue!=selected){endTargets.push_back(cue->id);endTarget.addItem(cue->title->stringValue(),int(endTargets.size()));if(cue->id==selected->target->stringValue().toStdString())endTarget.setSelectedId(int(endTargets.size()),dontSendNotification);}visit(cue->children);}};visit(coordinator()->cues);endTarget.setTextWhenNothingSelected("Choose exact End target (missing stays broken)");}part.clear(dontSendNotification);part.addItem("Cue / step settings",1);for(size_t i=0;i<selected->actions.size();++i){auto k=selected->actions[i]->kind;part.addItem(String(int(i+1))+" - "+(k==Kind::Move?"Movement":k==Kind::Link?"Link":"Haptic"),int(i+2));}if(selected->type==CueType::Mapping)part.addItem("Cue-owned native Mapping editor",100);if(selected->type==CueType::Package)part.addItem("Package parameters and aliases",101);actionCount=int(selected->actions.size());part.setSelectedId(1,dontSendNotification);bindEditor();}
 void bindEditor(){viewport.setViewedComponent(nullptr,false);editor.reset();packageEditor.reset();if(!selected)return;try{int n=part.getSelectedId()-2;if(part.getSelectedId()==101){packageEditor=std::make_unique<PackageInspector>(*selected);editor.reset(packageEditor->getEditor(false));}else if(part.getSelectedId()==100){editor.reset(authorMapping(*selected).getEditor(false));}else if(n>=0&&n<int(selected->actions.size()))editor.reset(selected->actions[n]->getEditor(false));else editor.reset(selected->getEditor(false));if(editor)viewport.setViewedComponent(editor.get(),false);resized();}catch(const std::exception& e){error.setText(e.what(),dontSendNotification);}}
 void timerCallback()override{auto* c=coordinator();auto current=c->find(c->selected);if(current!=selected){selected=current;bound=c->selected;if(selected)rebuild();else{viewport.setViewedComponent(nullptr,false);editor.reset();part.clear();}}if(selected){bool motion=selected->type==CueType::Motion||selected->type==CueType::Step;for(auto* b:{&addMove,&addLink,&addHaptic})b->setEnabled(motion);fromTake.setEnabled(motion||selected->type==CueType::Mapping||selected->type==CueType::Package);fromTake.setButtonText(selected->type==CueType::Package?"Load package folder":selected->type==CueType::Mapping?"Link existing Mapping":"Use recording");title.setText(selected->title->stringValue()+" | "+cueTypeName(selected->type),dontSendNotification);if(actionCount!=int(selected->actions.size()))rebuild();}else title.setText("Select a cue to inspect. Selection emits no output.",dontSendNotification);}
 void resized()override{auto r=getLocalBounds().reduced(8);title.setBounds(r.removeFromTop(30));part.setBounds(r.removeFromTop(28));if(endTarget.isVisible())endTarget.setBounds(r.removeFromTop(28));r.removeFromTop(4);auto row=r.removeFromTop(30);addMove.setBounds(row.removeFromLeft(row.getWidth()/4).reduced(2));addLink.setBounds(row.removeFromLeft(row.getWidth()/3).reduced(2));addHaptic.setBounds(row.removeFromLeft(row.getWidth()/2).reduced(2));fromTake.setBounds(row.reduced(2));error.setBounds(r.removeFromBottom(24));viewport.setBounds(r);if(editor)editor->setSize(jmax(240,viewport.getWidth()-18),editor->getHeight());}
};
class ActivePanel final:public ShapeShifterContentComponent,private ListBoxModel,private Timer {
public:
 ListBox rows;TextEditor diagnostics;Label info;OwnedArray<TextButton> buttons;std::vector<Id> ids;Id chosen;uint64_t generation=0;
 explicit ActivePanel(const String& name):ShapeShifterContentComponent(name){rows.setModel(this);rows.setRowHeight(50);rows.setColour(ListBox::backgroundColourId,Colour(0xff101822));diagnostics.setColour(TextEditor::backgroundColourId,Colour(0xff111a24));diagnostics.setColour(TextEditor::textColourId,Colours::lightgrey);addAndMakeVisible(rows);addAndMakeVisible(diagnostics);addAndMakeVisible(info);diagnostics.setMultiLine(true);diagnostics.setReadOnly(true);diagnostics.setScrollbarsShown(true);
 add("End selected run",[this]{coordinator()->end(chosen,generation);});add("Retry failed members",[this]{coordinator()->retry(chosen);});add("Group Next",[this]{coordinator()->next(chosen);});add("Pause song",[this]{coordinator()->pause(chosen,true);});add("Resume song",[this]{coordinator()->pause(chosen,false);});add("Deactivate inputs",[this]{auto r=coordinator()->runs.at(chosen);for(auto p:r->inputs)coordinator()->deactivateInput(chosen,p.first);});startTimerHz(5);}
 static ShapeShifterContent* create(const String& s){return new ActivePanel(s);}~ActivePanel()override{stopTimer();rows.setModel(nullptr);}
 void add(const String& label,std::function<void()> fn){auto* b=buttons.add(new TextButton(label));addAndMakeVisible(b);b->onClick=[this,fn]{try{require(!chosen.empty(),"Select a run");fn();info.setText({},dontSendNotification);}catch(const std::exception& e){info.setText(e.what(),dontSendNotification);}};}
 int getNumRows()override{return int(ids.size());}void selectedRowsChanged(int row)override{if(row>=0&&row<int(ids.size())){chosen=ids[row];generation=coordinator()->runs[chosen]->generation;}}
 void paintListBoxItem(int row,Graphics& g,int w,int h,bool selected)override{if(row<0||row>=int(ids.size()))return;auto* c=coordinator();auto r=c->runs[ids[row]];g.fillAll(selected?Colour(0xff264863):Colour(0xff151f2b));g.setColour(r->outcome==Outcome::Failed?Colours::orange:Colours::whitesmoke);String text=r->cue->name+" | "+outcomeName(r->outcome)+(c->owns(*r)?" | OWNED / HELD":"")+" | "+r->detail;g.drawFittedText(text,6,1,w-12,h-2,Justification::centredLeft,2);}
 void timerCallback()override{auto* c=coordinator();ids.clear();std::vector<std::shared_ptr<Run>> ordered;for(auto p:c->runs)ordered.push_back(p.second);std::sort(ordered.begin(),ordered.end(),[](auto a,auto b){return a->generation<b->generation;});for(auto r:ordered)ids.push_back(r->id);rows.updateContent();rows.repaint();String text;auto begin=c->log.size()>70?c->log.size()-70:0;for(size_t i=begin;i<c->log.size();++i)text+=c->log[i]+"\n";if(diagnostics.getText()!=text){diagnostics.setText(text,false);diagnostics.moveCaretToEnd();}}
 void resized()override{auto r=getLocalBounds().reduced(8);for(int line=0;line<2;++line){auto row=r.removeFromTop(30);for(int n=0;n<3;++n)buttons[line*3+n]->setBounds(row.removeFromLeft(row.getWidth()/(3-n)).reduced(2));}info.setBounds(r.removeFromTop(26));diagnostics.setBounds(r.removeFromBottom(r.getHeight()/3));rows.setBounds(r);}
};
}
